/// <reference types="cypress" />

/*
 * ./big is generated by "npm run generate" and is about 45 MB of plain JavaScript. Importing it
 * is the whole point of this spec: it makes the spec bundle large. "modules" is read below so
 * that no part of the graph can be dropped as unused.
 */
import { modules } from '../../big/index.js'

describe('page', () => {
  it('works', () => {
    cy.log(`big module graph: ${modules.length} modules`)
    cy.visit('https://example.cypress.io')
    cy.log('the visit returned')
  })
})
